public class InnerUserPoolRegionalConfigurationAttachmentLambdaConfigFactory(Action<Humidifier.Cognito.UserPoolRegionalConfigurationAttachmentTypes.LambdaConfig> factoryAction = null) : SubResourceFactory<Humidifier.Cognito.UserPoolRegionalConfigurationAttachmentTypes.LambdaConfig>
{

    internal InnerUserPoolRegionalConfigurationAttachmentInboundFederationFactory InboundFederationFactory { get; set; }

    internal InnerUserPoolRegionalConfigurationAttachmentCustomSMSSenderFactory CustomSMSSenderFactory { get; set; }

    internal InnerUserPoolRegionalConfigurationAttachmentPreTokenGenerationConfigFactory PreTokenGenerationConfigFactory { get; set; }

    internal InnerUserPoolRegionalConfigurationAttachmentCustomEmailSenderFactory CustomEmailSenderFactory { get; set; }

    protected override Humidifier.Cognito.UserPoolRegionalConfigurationAttachmentTypes.LambdaConfig Create()
    {
        var lambdaConfigResult = CreateLambdaConfig();
        factoryAction?.Invoke(lambdaConfigResult);

        return lambdaConfigResult;
    }

    private Humidifier.Cognito.UserPoolRegionalConfigurationAttachmentTypes.LambdaConfig CreateLambdaConfig()
    {
        var lambdaConfigResult = new Humidifier.Cognito.UserPoolRegionalConfigurationAttachmentTypes.LambdaConfig();

        return lambdaConfigResult;
    }
    public override void CreateChildren(Humidifier.Cognito.UserPoolRegionalConfigurationAttachmentTypes.LambdaConfig result)
    {
        base.CreateChildren(result);

        result.InboundFederation ??= InboundFederationFactory?.Build();
        result.CustomSMSSender ??= CustomSMSSenderFactory?.Build();
        result.PreTokenGenerationConfig ??= PreTokenGenerationConfigFactory?.Build();
        result.CustomEmailSender ??= CustomEmailSenderFactory?.Build();
    }

} // End Of Class

